pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 depositAmt, uint256 withdrawAmt, address actor) public {
        vm.assume(actor != address(c));
        depositAmt = bound(depositAmt, 1, type(uint256).max / 2);
        withdrawAmt = bound(withdrawAmt, 1, depositAmt);

        vm.deal(actor, depositAmt);
        vm.prank(actor);
        c.deposit{value: depositAmt}();

        vm.prank(actor);
        c.withdraw(withdrawAmt);

        uint256 beforeRefund = actor.balance;
        vm.prank(actor);
        c.refund();
        uint256 refunded = actor.balance - beforeRefund;

        // General rule: refund() pays out exactly the remaining credited balance,
        // which after deposit d and withdrawal a must be d - a.
        assertTrue(refunded == depositAmt - withdrawAmt);
    }
}

