pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(uint256 d, uint256 a, address actor) public {
        vm.assume(uint160(actor) > 0xFF);
        vm.assume(actor.code.length == 0);
        d = bound(d, 1, 1e30);
        a = bound(a, (d / 2) + 1, d); // ensures a > d - a

        vm.deal(actor, d);
        vm.prank(actor);
        c.deposit{value: d}();

        vm.prank(actor);
        c.withdraw(a);

        // Rule: a second withdrawal of the same amount must fail because only d-a remains.
        bool ok;
        vm.prank(actor);
        try c.withdraw(a) { ok = true; } catch { ok = false; }

        assertTrue(!ok);
    }
}

