import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(uint256 depositAmt, uint256 w1, uint256 w2) public {
        depositAmt = bound(depositAmt, 1, 1 ether);
        w1 = bound(w1, 0, depositAmt);
        // pick w2 strictly greater than the remaining balance (depositAmt - w1)
        w2 = bound(w2, depositAmt - w1 + 1, depositAmt + 1 ether);

        vm.deal(address(this), depositAmt);
        c.deposit{value: depositAmt}();
        // creator (this test contract) withdraws w1; balance becomes depositAmt - w1 in P
        c.withdraw(w1);

        bool ok;
        try c.withdraw(w2) { ok = true; } catch { ok = false; }

        // Rule: a second withdrawal exceeding the remaining balance must revert
        assertTrue(!ok, "over-withdrawal must revert");
    }

    receive() external payable {}
}

