pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address actor, address to, uint256 amount) public {
        vm.assume(actor != address(0));
        vm.assume(to != address(0));
        vm.assume(to != address(c));
        amount = bound(amount, 2, 100 ether);
        vm.deal(actor, amount);
        vm.prank(actor);
        c.deposit{value: amount}();
        vm.prank(c.creator());
        c.migrateTo(to);
        assertEq(address(c).balance, 0);
    }
}

contract InvMutTest {
    C c;

    constructor(C _c) { c = _c; }

    function test(uint256 a, uint256 b) public {
        require(address(this).balance >= a + b);
        c.deposit{value: a}();
        c.deposit{value: b}();
        (bool ok, ) = address(c).call(abi.encodeWithSelector(c.withdraw.selector, a + b));
        assert(ok);
    }
}

contract InvMutTest {
    C c;

    constructor(C _c) { c = _c; }

    function test(uint256 amount) public {
        require(amount > 0);
        require(address(this).balance >= amount);
        c.deposit{value: amount}();
        uint256 balBefore = address(c).balance;
        (bool ok, ) = address(c).call(abi.encodeWithSelector(C.migrateTo.selector, address(this)));
        assert(address(c).balance == balBefore);
    }
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(uint256 amount) public payable {
        require(address(this).balance >= amount);
        require(c.creator() != address(this));
        bool reverted;
        try c.migrateTo(address(0x1)) { reverted = false; } catch { reverted = true; }
        assert(reverted);
    }
    receive() external payable {}
}

